import { expect, test, type Page } from '@playwright/test';
import { readFile } from 'node:fs/promises';
import { PDFDocument } from 'pdf-lib';

// The bundled Help-tour sample: a genuinely signed, three-revision PDF with
// one signed (Provider_Signature) and one empty (Client_Signature) signature
// field. Regenerated by `npm run build:demo-sample`.
const SAMPLE_PDF = 'app/public/assets/demo/pdf-seal-sample.pdf';

async function uploadSample(page: Page, path = '/'): Promise<void> {
  await page.goto(path);
  await page.locator('#mainFileInput').setInputFiles(SAMPLE_PDF);
  await expect(page.locator('#viewerFileName')).toHaveText('pdf-seal-sample.pdf');
  await expect(page.locator('#documentLoadingOverlay')).toBeHidden();
}

test.describe('working with a document', () => {
  test('Overview summarises an uploaded PDF', async ({ page }) => {
    await uploadSample(page);
    const overview = page.locator('#sectionMetaData');
    await expect(overview).toContainText('PDF Seal Sample Document');
    await expect(overview).toContainText('PDF Seal Demo');
    await expect(overview).toContainText('Provider_Signature');
    await expect(overview).toContainText('Client_Signature');
    await expect(page.locator('#pageCount')).toHaveText('2');
    await expect(page.locator('#btnShare')).toBeEnabled();
  });

  test('loads the bundled sample from the empty state', async ({ page }) => {
    await page.goto('/');
    await page.locator('#emptyStateSampleBtn').click();
    await expect(page.locator('#viewerFileName')).toHaveText('pdf-seal-sample.pdf');
    await expect(page.locator('#sectionMetaData')).toContainText('PDF Seal Sample Document');
  });

  test('Certificates inspects the existing signature', async ({ page }) => {
    await uploadSample(page, '/certificates');
    const signatures = page.locator('#certSignatureList');
    await expect(signatures).toContainText('Alex Morgan');
    await expect(signatures).toContainText('Provider_Signature');
    await expect(page.locator('#certificatesSummaryPanel')).toContainText(/CERTIFICATES\s*3/i);
  });

  test('places a signature field, applies it and records a new version', async ({ page }) => {
    await uploadSample(page, '/signatures');
    const hero = page.locator('#sigSectionHero');
    await expect(hero).toContainText('2 signature fields');

    await page.locator('#sigName').fill('E2E_Signature');
    await page.locator('#btnPlaceField').click();
    await page.locator('#pdf-canvas').click({ position: { x: 200, y: 600 } });
    await expect(page.locator('#pendingChangesLabel')).toHaveText('1 unsaved change');
    await expect(page.locator('.field-overlay[data-field-name="E2E_Signature"]')).toBeVisible();

    await page.locator('#btnApplyFieldChanges').click();
    await expect(hero).toContainText('3 signature fields');
    await expect(hero).toContainText('2 unsigned · 1 signed');

    await page.locator('.section-nav-btn[data-section="revisions"]').click();
    const timeline = page.locator('#revisionsTimeline');
    await expect(timeline).toContainText('Version 4');
    await expect(timeline).toContainText(/current/i);
  });

  test('downloads the edited PDF with the new field in it', async ({ page }) => {
    await uploadSample(page, '/signatures');
    await page.locator('#sigName').fill('Downloaded_Signature');
    await page.locator('#btnPlaceField').click();
    await page.locator('#pdf-canvas').click({ position: { x: 200, y: 600 } });
    await page.locator('#btnApplyFieldChanges').click();
    await expect(page.locator('#sigSectionHero')).toContainText('3 signature fields');

    await page.locator('#btnDownloadToggle').click();
    await page.locator('#exportPdfBtn').click();
    await page.locator('#saveAsFileName').fill('e2e-output');
    const [download] = await Promise.all([page.waitForEvent('download'), page.locator('#confirmSaveAsBtn').click()]);

    expect(download.suggestedFilename()).toMatch(/^e2e-output.*\.pdf$/);
    const bytes = await readFile(await download.path());
    expect(bytes.subarray(0, 5).toString('latin1')).toBe('%PDF-');
    const fieldNames = (await PDFDocument.load(bytes)).getForm().getFields().map((f) => f.getName());
    expect(fieldNames).toEqual(expect.arrayContaining(['Provider_Signature', 'Client_Signature', 'Downloaded_Signature']));
  });
});
